// Ensemble A/B of the LogH kick: random binaries and hierarchical triples, adaptive GBS (eta, Bulirsch, k_max 8),
// 20 inner orbits. Prints per-system |dE/E|, |dL|/L, substeps; -DCTRL for the 1/(-U) kick.
// Build (from the repository root; logh_ctrl.cpp: python3.11 tests/enzyme/symplectic/make_ctrl.py <dir>):
//   clang++ -std=c++20 -O2 -fplugin=ClangEnzyme-18.so -Isrc/collisional tests/enzyme/symplectic/ens.cpp -o ens
//   (plain g++ (no Enzyme); -DCTRL -I<dir of logh_ctrl.cpp> for the 1/(-U) kick; args: eta n_systems)
#ifdef CTRL
#include "logh_ctrl.cpp"   // generated by make_ctrl.py
#else
#include "../../../src/collisional/logh.cpp"
#endif
#include "../../../src/collisional/logh_step.cpp"
#include "../../../src/collisional/post_newtonian_core.cpp"
#include <cstdio>
#include <cstdlib>
#include <random>

static const int SEQ[] = {2, 4, 6, 8, 12, 16, 24, 32, 48, 64};
static void kep(double mu, double a, double e, double inc, double Om, double w, double f, double* x, double* v) {
    const double p = a * (1 - e * e), r = p / (1 + e * std::cos(f));
    double X[3] = {r * std::cos(f), r * std::sin(f), 0}, V[3] = {-std::sin(f) * std::sqrt(mu / p), (e + std::cos(f)) * std::sqrt(mu / p), 0};
    for (double* q : {X, V}) {
        double b0 = std::cos(w) * q[0] - std::sin(w) * q[1], b1 = std::sin(w) * q[0] + std::cos(w) * q[1];
        double c1 = std::cos(inc) * b1, c2 = std::sin(inc) * b1;
        q[0] = std::cos(Om) * b0 - std::sin(Om) * c1; q[1] = std::sin(Om) * b0 + std::cos(Om) * c1; q[2] = c2;
    }
    for (int k = 0; k < 3; k++) { x[k] = X[k]; v[k] = V[k]; }
}
int main(int argc, char** argv) {
    const double eta = argc > 1 ? std::atof(argv[1]) : 1e-10;
    const int nsys = argc > 2 ? std::atoi(argv[2]) : 200;
    std::mt19937_64 rng(12345);
    std::uniform_real_distribution<double> U(0.0, 1.0);
    for (int sidx = 0; sidx < nsys; sidx++) {
        LogHState s; std::memset(&s, 0, sizeof(s));
        const bool tri = sidx % 2;
        const double e = std::sqrt(U(rng)) * 0.999, f = 2 * M_PI * U(rng);
        const double m1 = 0.2 + U(rng), m2 = 0.2 + U(rng);
        double x[3], v[3];
        kep(m1 + m2, 1.0, e, 0, 0, 0, f, x, v);
        s.n_bodies = tri ? 3 : 2;
        s.mass[0] = m1; s.mass[1] = m2;
        for (int k = 0; k < 3; k++) { s.pos[k] = -m2 / (m1 + m2) * x[k]; s.pos[3 + k] = m1 / (m1 + m2) * x[k]; s.vel[k] = -m2 / (m1 + m2) * v[k]; s.vel[3 + k] = m1 / (m1 + m2) * v[k]; }
        if (tri) {
            const double m3 = 0.1 + U(rng), M = m1 + m2 + m3, ao = 3.0 + 7.0 * U(rng), eo = 0.6 * U(rng);
            double X[3], V[3];
            kep(M, ao, eo, M_PI * U(rng), 2 * M_PI * U(rng), 2 * M_PI * U(rng), 2 * M_PI * U(rng), X, V);
            s.mass[2] = m3;
            for (int k = 0; k < 3; k++) {
                for (int b = 0; b < 2; b++) { s.pos[3 * b + k] -= m3 / M * X[k]; s.vel[3 * b + k] -= m3 / M * V[k]; }
                s.pos[6 + k] = (m1 + m2) / M * X[k]; s.vel[6 + k] = (m1 + m2) / M * V[k];
            }
        }
        s.B = -logh_total_energy(s, 1.0);
        const double E0 = logh_total_energy(s, 1.0);
        double L0[3] = {0, 0, 0};
        auto Lv = [&](double* L) { L[0] = L[1] = L[2] = 0; for (int i = 0; i < s.n_bodies; i++) { const double *q = s.pos + 3 * i, *w = s.vel + 3 * i; L[0] += s.mass[i] * (q[1] * w[2] - q[2] * w[1]); L[1] += s.mass[i] * (q[2] * w[0] - q[0] * w[2]); L[2] += s.mass[i] * (q[0] * w[1] - q[1] * w[0]); } };
        Lv(L0);
        const double P = 2 * M_PI / std::sqrt(m1 + m2);
        GbsParams par; par.seq = SEQ; par.k_max = 8; par.eta = eta;
        GbsTable tab;
        double ds = P * m1 * m2 / 20;
        long steps = 0, sub = 0;
        while (s.t < 20 * P && steps < 400000) {
            LogHStepStart st; logh_step_start(s, 1.0, 0.0, 0, st);
            GbsStepOut o; gbs_step(par, s, ds, tab, -1, &st, o);
            for (int k = 0; k <= o.stage; k++) sub += SEQ[k];
            steps++; ds = o.ds_next;
        }
        double L1[3]; Lv(L1);
        const double Ln = std::sqrt(L0[0] * L0[0] + L0[1] * L0[1] + L0[2] * L0[2]);
        double dL = 0; for (int k = 0; k < 3; k++) dL = std::max(dL, std::fabs(L1[k] - L0[k]));
        std::printf("%d %d %.4f %.3e %.3e %ld\n", sidx, tri ? 3 : 2, e, std::fabs(logh_total_energy(s, 1.0) / E0 - 1), dL / Ln, sub);
    }
}
